&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;x_msonormal&quot;&gt;Ogilvy’s influencer marketing practice is the largest globally; we are proud to be the most awarded influencer agency for eight years running and the recipient of the Cannes Grand Prix for Social &amp;amp; Creator for two consecutive years.  &lt;/span&gt;&lt;/span&gt;&amp;nbsp;&lt;br&gt;&amp;nbsp;&lt;br&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;The Role:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;x_ms-outlook-mobile-reference-message&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;9a4b8e33-69e6-51b1-9db3-96803dedf16a|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Times New Roman&amp;quot;,469777842,&amp;quot;Times New Roman&amp;quot;,469777843,&amp;quot;Times New Roman&amp;quot;,469777844,&amp;quot;Times New Roman&amp;quot;,201341986,&amp;quot;1&amp;quot;,469769226,&amp;quot;Times New Roman&amp;quot;,268442635,&amp;quot;24&amp;quot;,469775450,&amp;quot;x_ms-outlook-mobile-reference-message&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;xms-outlook-mobile-reference-message&amp;quot;,335572020,&amp;quot;1&amp;quot;,335559740,&amp;quot;240&amp;quot;,201341983,&amp;quot;0&amp;quot;,134233118,&amp;quot;true&amp;quot;,134233117,&amp;quot;true&amp;quot;,469778324,&amp;quot;Normal&amp;quot;]}&quot;&gt;As &lt;/span&gt;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;x_ms-outlook-mobile-reference-message&quot;&gt;Business Director&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;x_ms-outlook-mobile-reference-message&quot;&gt;&amp;nbsp;you will lead client partnership, strategic counsel and integrated delivery across the&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_ms-outlook-mobile-reference-message&quot;&gt; portfolio,&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_ms-outlook-mobile-reference-message&quot;&gt; designed to provide the client with fully focused, senior leadership on &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;x_ms-outlook-mobile-reference-message&quot;&gt;some of &lt;/span&gt;&lt;spa