&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;72d9cead-5d7c-511f-a089-41bc1b2ad175|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[335559740,&amp;quot;253&amp;quot;,201341983,&amp;quot;2&amp;quot;,469777841,&amp;quot;Arial&amp;quot;,469777842,&amp;quot;Arial&amp;quot;,469777843,&amp;quot;Times New Roman&amp;quot;,469777844,&amp;quot;Arial&amp;quot;,469769226,&amp;quot;Arial,Times New Roman&amp;quot;,268442635,&amp;quot;22&amp;quot;,469775450,&amp;quot;Body text Optiver&amp;quot;,201340122,&amp;quot;2&amp;quot;,134234082,&amp;quot;true&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;BodytextOptiver&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Zsysbasis Optiver&amp;quot;]}&quot;&gt;Y&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;ou’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; join a culture of collaboration and excellence, where &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;you’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; be surrounded by curious thinkers and creative problem solvers. Motivated by a passion for continuous improvement, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;you’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; thrive in a supportive, high-performing environment alongside talented colleagues, working collectively to tackle the toughest problems in the financial markets.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;In addition, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;you’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; receive:&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A performance-based bonus structure, enabling all of our employees to benefit from our global profit pool.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;27 paid vacation days plus all UK public holidays.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;Daily breakfast and lunch, along with support on commuting expenses.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;Private medical insurance, pension scheme, and &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;ClassPass&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt; fitness membership.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body text Optiver&quot;&gt;Training and continuous learning opportunities, including access to conferences and tech events.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:2,&amp;quot;335559740&amp;quot;:253}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
