&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience&amp;nbsp;working&amp;nbsp;with CI/CD pipelines&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
